/* * @lc app=leetcode id=2909 lang=kotlin * * [2909] Minimum Sum of Mountain Triplets II */ class Solution { fun minimumSum(nums: IntArray): Int = IntArray(nums.size).also { left -> nums.indices.fold(Int.MAX_VALUE) { m, i -> minOf(m, nums[i]).also { left[i] = it } } }.let { left -> IntArray(nums.size).also { right -> nums.indices.reversed().fold(Int.MAX_VALUE) { m, i -> minOf(m, nums[i]).also { right[i] = it } } }.let { right -> (1 until nums.size - 1).filter { j -> left[j - 1] < nums[j] && right[j + 1] < nums[j] }.minOfOrNull { j -> left[j - 1] + nums[j] + right[j + 1] } ?: -1 } } }